const songs = [
  {
    name: "Les Toreadors",
    tracks: lesToreadors,
    duration: 146000
  },
  {
    name: "Song of Storms",
    tracks: songOfStorms,
    duration: 101000
  },
  {
    name: "Metal Crusher",
    tracks: metalCrusher,
    duration: 63000
  },
  {
    name: "The Third Time",
    tracks: theThirdTime,
    duration: 158000
  },
  {
    name: "Sort Or 'Splode",
    tracks: sortOrSplode,
    duration: 100000
  }
]

var currentSong = 0
var musicEnabled = false
var songQueue = []
var songTimer = null
var playbacks = []

function shuffleSongs() {
  songQueue = []

  for (let i = 0; i < songs.length; i++) {
    songQueue.push(i)
  }

  for (let i = songQueue.length - 1; i > 0; i--) {
    let j = Math.floor(Math.random() * (i + 1))
    let temp = songQueue[i]
    songQueue[i] = songQueue[j]
    songQueue[j] = temp
  }
}

function stopMusic() {
  musicEnabled = false

  if (songTimer != null) {
    clearTimeout(songTimer)
    songTimer = null
  }

  playbacks.forEach((p) => p.end())
  playbacks = []
}

function playSong(songIndex) {
  stopMusic()

  currentSong = songIndex
  musicEnabled = true

  song = songs[currentSong]

  song.tracks.forEach((track) => {
    playbacks.push(playTune(track))
  })

  songTimer = setTimeout(() => {
    if (musicEnabled) {
      playNextSong()
    }
  }, song.duration)
}

function playNextSong() {
  if (songQueue.length === 0) {
    shuffleSongs()
  }

  setTimeout(() => {
    playSong(songQueue.shift())
    let songDisp = addText(song.name, {x:0, y:15, color: color`2`})
  }, 3000)


  setTimeout(() => {songDisp = addText("                             ", {x:0, y:15, color: color`2`})}, 5000)
}

// L: Start the random playlist
onInput("l", () => {
  if (!musicEnabled) {
    if (songQueue.length === 0) {
      shuffleSongs()
    }

    playNextSong()
  }
})

// I: Skip to the next song
onInput("i", () => {
  if (songQueue.length === 0) {
    shuffleSongs()
  }

  playNextSong()
})

// K: Stop music
onInput("k", () => {
  stopMusic()
})


onInput("w", () => {
  if (selectorShowing == true) {
    if (currentSelectorY > 1) {
      currentSelectorY -= 1
    }
  }
})

onInput("a", () => {
  if (selectorShowing == true) {
    if(currentSelectorX > 2) {
      currentSelectorX -= 1
    }
  }
})

onInput("s", () => {
  if (selectorShowing == true) {
    if(currentSelectorY < 8) {
      currentSelectorY += 1
    }
  }
})

onInput("d", () => {
  if (selectorShowing == true) {
    if(currentSelectorX < 9) {
      currentSelectorX += 1
    }
  }
})

onInput("j", () => {
  if (startScreen) {
    startScreen = false

    clearText()
    setMap(levels[0])
    setBoard()

    currentSelectorX = 3
    currentSelectorY = 2
    currentSelectorSprite = 1

    addSprite(currentSelectorX, currentSelectorY, selector1)
    return
  }

  if (gameOver) return

  if (!selectorShowing) return

  let targetDot = getAll(moveableDot).find(
    dot => dot.x == currentSelectorX &&
           dot.y == currentSelectorY
  )

  if (selectedPiece != undefined && targetDot != undefined) {
    movePiece(targetDot.x, targetDot.y)
  } else {
    let piece = pieceFinder()

    if (piece != undefined && isPlayersPiece(piece)) {
      selectedPiece = piece
      showPossibleMoves()
    } else {
      selectedPiece = undefined
      getAll(moveableDot).forEach(dot => dot.remove())
    }
  }
})

